import { test, type Page } from '@playwright/test';

const focusDesc = (page: Page) =>
  page.evaluate(() => {
    const a = document.activeElement as HTMLElement | null;
    if (!a) return 'none';
    return `${a.tagName} role=${a.getAttribute('role')} name=${a.getAttribute('aria-label') ?? a.textContent?.trim().slice(0, 40)} inDialog=${!!a.closest('[role=dialog]')}`;
  });
const alerts = (page: Page) =>
  page.evaluate(() =>
    [...document.querySelectorAll('[role=alert],[role=status]')]
      .map((e) => `${e.getAttribute('role')}: ${e.textContent?.trim().slice(0, 80)}`)
      .filter((s) => !s.endsWith(': ')),
  );

for (const type of ['gcs', 'bigquery']) {
  test(`connection form ${type}`, async ({ page }) => {
    await page.goto('/connections/new');
    await page.waitForTimeout(1500);
    const label = type === 'gcs' ? /Google Cloud Storage/ : /BigQuery/;
    const card = page.getByRole('button', { name: label }).or(page.getByRole('radio', { name: label })).or(page.getByText(label)).first();
    await card.click();
    await page.waitForTimeout(800);
    console.log(type, await page.locator('main').ariaSnapshot());
  });
}

test('suites enable/disable + legacy promote', async ({ page, request }) => {
  const suites = (await (await request.get('/api/v1/suites')).json()) as { id: string; name: string }[];
  const suite = suites.find((s) => s.name === 'Orders quality')!;
  const put = await request.put(`/api/v1/suites/${suite.id}/notifications`, {
    data: { enabled: true, alert_on: 'fail', webhook: 'https://example.invalid/hook', email_recipients: 'a@example.com' },
  });
  console.log('put', put.status(), (await put.text()).slice(0, 200));
  await page.goto(`/suites/${suite.id}`);
  await page.waitForTimeout(2000);
  const dis = page.getByRole('button', { name: /^Disable/ });
  console.log('disable buttons', await dis.count(), await dis.first().getAttribute('aria-label'));
  await dis.first().focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(1500);
  console.log('after disable focus:', await focusDesc(page));
  console.log('alerts:', await alerts(page));
  const en = page.getByRole('button', { name: /^Enable$/ });
  if (await en.count()) {
    await en.first().focus();
    await page.keyboard.press('Enter');
    await page.waitForTimeout(1500);
    console.log('after enable focus:', await focusDesc(page));
  }
  // bulk
  const boxes = page.getByRole('checkbox');
  console.log('checkboxes', await boxes.count());
  console.log(await page.locator('main').ariaSnapshot());
});

