import AxeBuilder from '@axe-core/playwright';
import { test, type Page } from '@playwright/test';

import { settle } from '../scripts/a11y/settle';
import { setupTrend } from './zz-helpers';

async function scan(page: Page, label: string, include?: string) {
  await settle(page);
  let b = new AxeBuilder({ page });
  if (include) b = b.include(include);
  const r = await b.analyze();
  const bad = r.violations.filter((v) => v.impact === 'serious' || v.impact === 'critical');
  console.log(
    label,
    bad.length ? bad.map((v) => `${v.id}: ${v.nodes.map((n) => n.target.join(' ')).join(' | ')}`) : 'clean',
  );
}

for (const mode of ['light', 'dark'] as const) {
  test.describe(mode, () => {
    test.beforeEach(async ({ page }) => {
      await page.addInitScript((m) => localStorage.setItem('dq-theme-mode', m), mode);
    });
    test('trend + promote + calendar', async ({ page, request }) => {
      const t = await setupTrend(page, request);
      try {
        await page.goto(`/suites/${t.suite}/checks/${t.check}/edit`);
        await page.getByRole('button', { name: 'Trend' }).click();
        await page.getByTestId('seasonal-caption').waitFor();
        await scan(page, `${mode} trend chart`, '.ant-drawer');
        await page.getByRole('button', { name: /Promote to calendar/ }).click();
        await page.getByRole('dialog', { name: 'Add this period to the calendar' }).waitFor();
        await scan(page, `${mode} promote modal`, '.ant-modal');
        await page.keyboard.press('Escape');
        await page.getByText('Table', { exact: true }).click();
        await scan(page, `${mode} trend table`, '.ant-drawer');
        await page.keyboard.press('Escape');
        await scan(page, `${mode} check editor`);
        await page.goto('/admin/calendar');
        await page.getByRole('button', { name: /Delete Audit BF/ }).click();
        await page.getByRole('dialog', { name: /^Delete/ }).getByRole('button', { name: 'Delete' }).click();
        await page.getByTestId('calendar-delete-blocked').waitFor();
        await scan(page, `${mode} calendar blocked`);
        await page.getByRole('button', { name: /New entry/ }).click();
        await page.getByRole('dialog', { name: 'New calendar entry' }).waitFor();
        await page.getByLabel('On specific dates').check();
        await scan(page, `${mode} calendar modal`, '.ant-modal');
      } finally {
        await t.cleanup();
      }
    });
    test('pii + coverage block + legacy + dashboard', async ({ page, request }) => {
      const assets: { id: string }[] = await (await request.get('/api/v1/assets')).json();
      const assetId = assets[0].id;
      await page.route(`**/api/v1/assets/${assetId}`, async (route) => {
        if (route.request().method() !== 'GET') return route.continue();
        const body = await (await route.fetch()).json();
        body.detected_classifications = [
          { column: 'email', detector: 'email', effect: 'masks', first_detected_at: '2026-10-01T00:00:00Z', last_detected_at: '2026-10-02T00:00:00Z', dismissed: false, dismissed_at: null },
          { column: 'blob', detector: 'encoded', effect: 'overridden_by_tag', first_detected_at: '2026-10-01T00:00:00Z', last_detected_at: '2026-10-02T00:00:00Z', dismissed: false, dismissed_at: null },
          { column: 'mail2', detector: 'email', effect: 'dismissed', first_detected_at: '2026-10-01T00:00:00Z', last_detected_at: '2026-10-02T00:00:00Z', dismissed: true, dismissed_at: '2026-10-03T00:00:00Z' },
        ];
        body.detected_classifications_refreshed_at = '2026-10-02T00:00:00Z';
        await route.fulfill({ json: body });
      });
      await page.goto(`/assets/${assetId}`);
      await page.getByTestId('detected-masking-panel').waitFor();
      await page.getByText('Sensitivity of this table’s automatic checks').click();
      await scan(page, `${mode} asset`);
      await page.route('**/api/v1/dashboard/coverage', async (route) => {
        const body = await (await route.fetch()).json();
        body.false_positives_by_baseline = [{ key: 'volume', label: 'Row count', false_positive: 2, stated: 5, rate: 40 }];
        body.false_positives_by_connection = [{ key: 'c', label: 'snowflake-analytics', false_positive: 2, stated: 5, rate: 40 }];
        await route.fulfill({ json: body });
      });
      await page.goto('/dashboard');
      await page.getByTestId('coverage-panel').waitFor();
      await scan(page, `${mode} dashboard`, '[data-testid=coverage-panel]');
      const suites = (await (await request.get('/api/v1/suites')).json()) as { id: string; name: string }[];
      const suite = suites.find((s) => s.name === 'Orders quality')!;
      await page.route(`**/api/v1/suites/${suite.id}/notifications`, async (route) => {
        if (route.request().method() !== 'GET') return route.continue();
        const body = await (await route.fetch()).json();
        body.has_webhook = true;
        await route.fulfill({ json: body });
      });
      await page.goto(`/suites/${suite.id}`);
      await page.getByText('Legacy inline destinations').waitFor();
      await scan(page, `${mode} suite legacy`);
      await page.getByRole('button', { name: /Promote/ }).first().click();
      await page.getByRole('dialog', { name: 'Promote to channel' }).waitFor();
      await scan(page, `${mode} legacy modal`, '.ant-modal');
    });
  });
}

